"""Remove the platform's own footer from what a session posted, when it follows the maintainer's.

WHY THIS SCRIPT EXISTS
----------------------
Everything a Claude Code session posts here ends with the maintainer's signature line, and the
platform's network layer appends a footer of its own after it: a "---" rule and
"_Generated by [Claude Code](...)_". Two signature lines say the same thing, and only the first
carries the maintainer's name. The session cannot remove the second: the platform writes it again
on every edit made from a session, through the "pulls" endpoint and the "issues" one alike. Only
code running on GitHub's side, with a token the platform does not wrap, can take it off for good --
which is "strip_tooling_footer.yml", with this file as its entrypoint.

WHAT IT DOES
------------
"stripped(body)" is the pure decision: the body without the footer, or None when there is nothing to
do. It acts only when one or more such footers close the body and the maintainer's signature stands
directly before them, blank lines apart. What it refuses to touch, so that a stranger cannot make it
rewrite text and a legitimate paragraph is never eaten:

* a footer with no signature right before it (a body of somebody else's, or a forged one);
* a signature followed by other text before the footer;
* a footer in the middle of a body, with text after it;
* a signature naming anybody but the maintainer.

The decision reads lines from the end with indices and matches each line against one anchored
pattern, so its cost is linear in the size of the body whatever the body holds.

"main()" reads the event from the file GitHub names in GITHUB_EVENT_PATH, and the body stays data: it
is never put in a shell command nor in a workflow expression. The event only says WHICH pull request,
issue or comment to look at: a run can start long after the event, so the script reads the object's
current state through the REST API and decides on that, never on the body the event carried. It
edits only when the author of that current state is the owner, a member or a collaborator of the
repository, since a stranger's text is none of this script's business. For a
manual run it sweeps every open issue and pull request once, so the posts that already exist are
cleaned too. It prints one line per edit, with the number and the kind and never the body.

An edit made with the job's own token starts no workflow, so nothing loops; and a run on text it has
already cleaned finds nothing to do, so it would be harmless if one did.

Run it from the repository root:

    python3 .github/scripts/strip_tooling_footer.py --selftest
"""

import contextlib
import io
import json
import os
import re
import sys
import tempfile
import time
import urllib.request
from pathlib import Path

SIGNATURE = re.compile(r"_Generated by \[Claude Code\]\(https://claude\.ai/code/session_[A-Za-z0-9_-]+\)"
                       r" and supervised by @tigerblue77\._")
# The platform writes the session's link on creation and the bare product link after an edit.
FOOTER = re.compile(r"_Generated by \[Claude Code\]\(https://claude\.ai/code(?:/session_[A-Za-z0-9_-]+)?\)_")
RULE = "---"

# Whose text the script may rewrite.
TRUSTED_ASSOCIATIONS = {"OWNER", "MEMBER", "COLLABORATOR"}
# A sweep reads at most this many pages: a bound, not a goal.
MAX_PAGES = 30
PER_PAGE = 100
TIMEOUT_SECONDS = 30


def stripped(body):
    """The body without the platform's footer(s), or None when there is nothing to remove."""
    if not isinstance(body, str):
        return None
    newline = "\r\n" if "\r\n" in body else "\n"
    lines = body.split("\n")

    def before_blanks(end):
        while end > 0 and not lines[end - 1].strip():
            end -= 1
        return end

    end = before_blanks(len(lines))
    removed = False
    while end > 0 and FOOTER.fullmatch(lines[end - 1].strip()):
        rule = before_blanks(end - 1)
        if rule == 0 or lines[rule - 1].strip() != RULE:
            break
        end = before_blanks(rule - 1)
        removed = True
    if not removed or end == 0 or not SIGNATURE.fullmatch(lines[end - 1].strip()):
        return None
    kept = [line.rstrip("\r") for line in lines[:end - 1]] + [lines[end - 1].strip()]
    return newline.join(kept) + newline


def clean(kind, number, obj, path, api):
    """Edit one object through `api` when it is trusted and carries a footer. 1 when it did."""
    if obj.get("author_association") not in TRUSTED_ASSOCIATIONS:
        return 0
    body = stripped(obj.get("body"))
    if body is None:
        return 0
    api("PATCH", path, {"body": body})
    print("edited %s %s" % (kind, number))
    return 1


def sweep(repo, api):
    """Every open issue and pull request, page by page, up to MAX_PAGES."""
    edited = 0
    for page in range(1, MAX_PAGES + 1):
        items = api("GET", "/repos/%s/issues?state=open&per_page=%d&page=%d" % (repo, PER_PAGE, page))
        if not items:
            break
        for item in items:
            kind = "pull request" if "pull_request" in item else "issue"
            number = item["number"]
            edited += clean(kind, number, item, "/repos/%s/issues/%s" % (repo, number), api)
        if len(items) < PER_PAGE:
            break
    return edited


def run(event_name, event, repo, api):
    """What the workflow does for one event. Returns the number of edits made."""
    if event_name == "workflow_dispatch":
        return sweep(repo, api)
    if event_name == "pull_request_target":
        kind, obj = "pull request", event.get("pull_request")
    elif event_name == "issues":
        kind, obj = "issue", event.get("issue")
    elif event_name == "issue_comment":
        kind, obj = "comment", event.get("comment")
    else:
        return 0
    if not isinstance(obj, dict):
        return 0
    if event_name == "issue_comment":
        path = "/repos/%s/issues/comments/%s" % (repo, obj["id"])
        number = obj["id"]
    else:
        path = "/repos/%s/issues/%s" % (repo, obj["number"])
        number = obj["number"]
    return clean(kind, number, api("GET", path), path, api)


def github_api(token):
    base = os.environ.get("GITHUB_API_URL", "https://api.github.com")

    def call(method, path, payload=None):
        request = urllib.request.Request(
            base + path, method=method,
            data=None if payload is None else json.dumps(payload).encode(),
            headers={"Authorization": "Bearer " + token, "Accept": "application/vnd.github+json",
                     "X-GitHub-Api-Version": "2022-11-28", "Content-Type": "application/json"})
        with urllib.request.urlopen(request, timeout=TIMEOUT_SECONDS) as response:
            return json.load(response)

    return call


def main():
    token = os.environ.get("GH_TOKEN", "")
    repo = os.environ.get("GITHUB_REPOSITORY", "")
    event_path = os.environ.get("GITHUB_EVENT_PATH", "")
    if not (token and repo and event_path):
        print("GH_TOKEN, GITHUB_REPOSITORY and GITHUB_EVENT_PATH must be set.", file=sys.stderr)
        return 1
    event = json.loads(Path(event_path).read_text(encoding="utf-8"))
    try:
        run(os.environ.get("GITHUB_EVENT_NAME", ""), event, repo, github_api(token))
    except OSError as error:
        # An HTTP error carries a status and a reason, never the body that was sent.
        print("GitHub API call failed: %s" % error, file=sys.stderr)
        return 1
    return 0


SIG = "_Generated by [Claude Code](https://claude.ai/code/session_01AbC-d_9) and supervised by @tigerblue77._"
FOOT_NEW = "_Generated by [Claude Code](https://claude.ai/code/session_01XyZ)_"
FOOT_EDIT = "_Generated by [Claude Code](https://claude.ai/code)_"


def selftest():
    # The handlers print one line per edit, which would bury the verdict.
    with contextlib.redirect_stdout(io.StringIO()):
        failures = _selftest()
    for failure in failures:
        print("FAIL " + failure, file=sys.stderr)
    print("selftest: %s" % ("%d failure(s)" % len(failures) if failures else "ok"))
    return 1 if failures else 0


def _selftest():
    failures = []

    def expect(label, got, want):
        if got != want:
            failures.append("%s: got %r, wanted %r" % (label, got, want))

    clean_body = "Texte.\n\n---\n" + SIG + "\n"
    for label, foot in (("creation footer", FOOT_NEW), ("edit footer", FOOT_EDIT)):
        expect(label, stripped("Texte.\n\n---\n" + SIG + "\n\n---\n" + foot), clean_body)
    expect("extra blank line before the rule", stripped("T\n---\n" + SIG + "\n\n\n---\n" + FOOT_EDIT + "\n\n"),
           "T\n---\n" + SIG + "\n")
    expect("blank lines between rule and footer", stripped("T\n" + SIG + "\n---\n\n" + FOOT_EDIT),
           "T\n" + SIG + "\n")
    expect("trailing whitespace", stripped("T\n" + SIG + "  \n\n---  \n" + FOOT_EDIT + " \t\n"),
           "T\n" + SIG + "\n")
    expect("crlf", stripped("T\r\n\r\n---\r\n" + SIG + "\r\n\r\n---\r\n" + FOOT_EDIT + "\r\n"),
           "T\r\n\r\n---\r\n" + SIG + "\r\n")
    expect("two stacked footers",
           stripped("T\n" + SIG + "\n\n---\n" + FOOT_NEW + "\n\n---\n" + FOOT_EDIT),
           "T\n" + SIG + "\n")
    expect("signature is the whole body", stripped(SIG + "\n---\n" + FOOT_NEW), SIG + "\n")
    expect("idempotent", stripped(stripped("T\n" + SIG + "\n---\n" + FOOT_NEW)), None)
    expect("no footer", stripped("T\n" + SIG + "\n"), None)
    expect("empty", stripped(""), None)
    expect("none", stripped(None), None)
    expect("footer without signature", stripped("T\n\n---\n" + FOOT_NEW), None)
    expect("footer only", stripped(FOOT_NEW), None)
    expect("signature then text then footer", stripped("T\n" + SIG + "\nautre\n---\n" + FOOT_NEW), None)
    expect("footer in the middle", stripped("T\n" + SIG + "\n---\n" + FOOT_NEW + "\nsuite\n"), None)
    expect("footer without its rule", stripped("T\n" + SIG + "\n" + FOOT_NEW), None)
    expect("footer after a longer rule", stripped("T\n" + SIG + "\n-----\n" + FOOT_NEW), None)
    expect("signature of someone else",
           stripped("T\n" + SIG.replace("tigerblue77", "someone") + "\n---\n" + FOOT_NEW), None)
    expect("signature with a bad session id",
           stripped("T\n" + SIG.replace("01AbC-d_9", "a b") + "\n---\n" + FOOT_NEW), None)
    expect("footer with a bad session id",
           stripped("T\n" + SIG + "\n---\n" + FOOT_NEW.replace("01XyZ", "a b")), None)
    expect("footer of another tool",
           stripped("T\n" + SIG + "\n---\n_Generated by [Other](https://claude.ai/code)_"), None)
    expect("text before the footer on its line", stripped("T\n" + SIG + "\n---\nvu " + FOOT_NEW), None)
    expect("text after the footer on its line", stripped("T\n" + SIG + "\n---\n" + FOOT_NEW + " suite"), None)
    expect("signature quoted inside a sentence",stripped("T " + SIG + "\n---\n" + FOOT_NEW), None)
    expect("footer after a signature after a footer",
           stripped("A\n" + FOOT_NEW + "\n" + SIG + "\n---\n" + FOOT_EDIT), "A\n" + FOOT_NEW + "\n" + SIG + "\n")
    expect("a footer before a signature is not touched",
           stripped("---\n" + FOOT_NEW + "\n" + SIG + "\n---\n" + FOOT_EDIT),
           "---\n" + FOOT_NEW + "\n" + SIG + "\n")
    expect("a footer, a rule and text, then signature and footer",
           stripped("---\n" + FOOT_NEW + "\nautre\n" + SIG + "\n---\n" + FOOT_EDIT),
           "---\n" + FOOT_NEW + "\nautre\n" + SIG + "\n")

    # A hostile body must cost linear time, not a backtracking explosion.
    stacked = "T\n" + SIG + "\n" + ("---\n" + FOOT_NEW + "\n") * 20000
    hostile = {
        "dashes and newlines": "-\n" * 500000,
        "one long line": "-" * 1000000,
        "newlines": "\n" * 1000000,
        "blank-separated rules ending in a footer": "---\n\n" * 200000 + FOOT_NEW,
        "repeated footers behind a signature": stacked,
        "almost-footers": ("_Generated by [Claude Code](https://claude.ai/code/session_" + "a" * 50 + "\n") * 10000,
    }
    for label, body in hostile.items():
        started = time.monotonic()
        stripped(body)
        elapsed = time.monotonic() - started
        if elapsed > 2:
            failures.append("hostile body (%s) took %.1f s" % (label, elapsed))
    expect("many stacked footers are all removed", stripped(stacked), "T\n" + SIG + "\n")

    # The event handling, against an API that records instead of calling. The event names the object;
    # what is decided on is the object's current state, served from `current`.
    calls = []

    def fake(pages=None, current=None):
        def api(method, path, payload=None):
            calls.append((method, path, payload))
            if method == "GET" and "page=" in path:
                return (pages or {}).get(int(path.rsplit("page=", 1)[1]), [])
            if method == "GET":
                found = (current or {})[path]
                if isinstance(found, Exception):
                    raise found
                return found
            return {}
        return api

    kinds = {
        "pull_request_target": ("pull_request", "/repos/o/r/issues/7", "number"),
        "issues": ("issue", "/repos/o/r/issues/7", "number"),
        "issue_comment": ("comment", "/repos/o/r/issues/comments/99", "id"),
    }

    def handle(name, event_body, current_body, association, current_association=None):
        """Run one event whose payload carries `event_body` while the object now holds `current_body`."""
        key, path, ident = kinds[name]
        event = {key: {ident: 7 if ident == "number" else 99, "body": event_body,
                       "author_association": association}}
        now = {"body": current_body, "author_association": current_association or association}
        del calls[:]
        return run(name, event, "o/r", fake(current={path: now})), path

    dirty = "T\n" + SIG + "\n---\n" + FOOT_NEW
    cleaned = "T\n" + SIG + "\n"
    for association in ("OWNER", "MEMBER", "COLLABORATOR"):
        for name in kinds:
            n, path = handle(name, dirty, dirty, association)
            expect("%s by %s" % (name, association), (n, calls),
                   (1, [("GET", path, None), ("PATCH", path, {"body": cleaned})]))
    for association in ("NONE", "CONTRIBUTOR", "FIRST_TIME_CONTRIBUTOR", "FIRST_TIMER", "MANNEQUIN", None):
        for name in kinds:
            n, path = handle(name, dirty, dirty, association)
            expect("stranger %s on %s is left alone" % (association, name), (n, calls),
                   (0, [("GET", path, None)]))
    # The author's trust is judged on the current state, not on the event's.
    n, path = handle("issues", dirty, dirty, "OWNER", current_association="NONE")
    expect("current author is a stranger", (n, calls), (0, [("GET", path, None)]))
    n, path = handle("issues", dirty, dirty, "NONE", current_association="OWNER")
    expect("current author is trusted", n, 1)

    edited = "Edited by hand.\n\n" + SIG + "\n\n---\n" + FOOT_EDIT + "\n"
    for name in kinds:
        n, path = handle(name, dirty, cleaned, "OWNER")
        expect("%s: the event carries a footer, the current body has none" % name, (n, calls),
               (0, [("GET", path, None)]))
        n, path = handle(name, dirty, edited, "OWNER")
        expect("%s: the PATCH carries the current text, not the event's" % name, (n, calls),
               (1, [("GET", path, None), ("PATCH", path, {"body": "Edited by hand.\n\n" + SIG + "\n"})]))
        n, path = handle(name, cleaned, dirty, "OWNER")
        expect("%s: the event is clean but the current body is not" % name, n, 1)
        n, path = handle(name, dirty, None, "OWNER")
        expect("%s: null current body" % name, (n, calls), (0, [("GET", path, None)]))
        key, path, ident = kinds[name]
        try:
            run(name, {key: {"number": 7, "id": 99}}, "o/r", fake(current={path: OSError("boom")}))
            failures.append("%s: a failing GET must raise" % name)
        except OSError:
            pass
    expect("unknown event", run("push", {}, "o/r", fake()), 0)
    expect("missing object", run("issues", {}, "o/r", fake()), 0)

    # A failing GET ends the whole run with exit 1, as a failing PATCH does.
    real_api, real_env = globals()["github_api"], dict(os.environ)
    try:
        with tempfile.TemporaryDirectory() as directory:
            event_file = Path(directory) / "event.json"
            event_file.write_text(json.dumps({"issue": {"number": 7, "body": dirty,
                                                        "author_association": "OWNER"}}))
            os.environ.update({"GH_TOKEN": "x", "GITHUB_REPOSITORY": "o/r", "GITHUB_EVENT_NAME": "issues",
                               "GITHUB_EVENT_PATH": str(event_file)})
            globals()["github_api"] = lambda token: fake(current={"/repos/o/r/issues/7": OSError("boom")})
            with contextlib.redirect_stderr(io.StringIO()):
                expect("exit code when the GET fails", main(), 1)
            globals()["github_api"] = lambda token: fake(
                current={"/repos/o/r/issues/7": {"body": dirty, "author_association": "OWNER"}})
            expect("exit code when it works", main(), 0)
    finally:
        globals()["github_api"] = real_api
        os.environ.clear()
        os.environ.update(real_env)

    del calls[:]
    pages = {1: [{"number": 1, "body": dirty, "author_association": "OWNER"},
                 {"number": 2, "body": dirty, "author_association": "NONE"},
                 {"number": 3, "body": dirty, "author_association": "MEMBER", "pull_request": {}},
                 {"number": 4, "body": cleaned, "author_association": "OWNER"}]}
    printed = io.StringIO()
    with contextlib.redirect_stdout(printed):
        edits = run("workflow_dispatch", {}, "o/r", fake(pages))
    expect("sweep count", edits, 2)
    expect("sweep prints a number and a kind, never the body", printed.getvalue(),
           "edited issue 1\nedited pull request 3\n")
    expect("a short page ends the sweep", [call[0] for call in calls], ["GET", "PATCH", "PATCH"])
    expect("sweep writes", [call for call in calls if call[0] == "PATCH"],
           [("PATCH", "/repos/o/r/issues/1", {"body": cleaned}), ("PATCH", "/repos/o/r/issues/3", {"body": cleaned})])
    del calls[:]
    full = {page: [{"number": 1000 * page + i, "body": cleaned, "author_association": "OWNER"}
                   for i in range(PER_PAGE)] for page in range(1, MAX_PAGES + 5)}
    run("workflow_dispatch", {}, "o/r", fake(full))
    expect("sweep is bounded", len(calls), MAX_PAGES)

    return failures


if __name__ == "__main__":
    sys.exit(selftest() if sys.argv[1:] == ["--selftest"] else main())
